const rankedItems = $items('Score Developer Tool Trends').map((item) => item.json).filter((item) => item.source_url);
const topicArchive = ($json?.recent || []).map((t) => `${t.tool_name}: ${t.topic} (${t.category})`);
const publisherCounts = new Map();
const categoryBuckets = new Map();
for (const item of rankedItems.sort((a, b) => b.trend_score - a.trend_score)) {
  const count = publisherCounts.get(item.publisher) ?? 0;
  if (count >= 6) continue;
  publisherCounts.set(item.publisher, count + 1);
  const category = item.content_category || 'other';
  if (!categoryBuckets.has(category)) categoryBuckets.set(category, []);
  categoryBuckets.get(category).push(item);
}
const sourceItems = [];
const categories = [...categoryBuckets.keys()];
while (sourceItems.length < 45 && categories.some((category) => categoryBuckets.get(category).length)) {
  for (const category of categories) {
    const next = categoryBuckets.get(category).shift();
    if (next) sourceItems.push(next);
    if (sourceItems.length >= 45) break;
  }
}
if (sourceItems.length < 5) throw new Error('RESEARCH_INSUFFICIENT_TOOL_SIGNALS');
const topicShape = {topic:'',tool_name:'',category:'',one_line_value:'',developer_workflow:'',who_it_helps:'',why_now:'',hook:'',why_it_matters:'',visual_angle:'',trend_score:0,claims:[{claim_id:'c1',statement:'',source_url:'',publisher:'',published_at:'',retrieved_at:new Date().toISOString(),confidence:0,verification_notes:''}],seo_brief:{primary_keyword:'',related_keywords:[''],search_intent:'informational|commercial|tutorial',title_options:['','',''],description:'',hashtags:['']}};
const schema = {recommended_topic:topicShape,candidates:[topicShape],research_policy:{requires_human_review:true,content_disclosure:'AI-assisted research and narration; edited visuals.'}};
const prompt = `You are an evidence-first researcher and SEO strategist for Databases & Performance, a short video show aimed at software developers. Analyze only the RANKED SOURCE MATERIAL below. Never invent product capabilities, adoption numbers, pricing, release dates, or market claims.

This show covers ONLY database query tricks, indexing, caching, connection pooling, and backend or application performance optimization techniques. Reject every candidate outside that scope, even a strong one -- a sibling show already covers other developer topics, and diluting this pool is exactly the mistake this show exists to avoid. If fewer than 5 source items are genuinely in scope, return fewer candidates rather than stretching the definition. Explain the concrete developer workflow improved.

Use trend_score as a discovery signal, not proof. Prefer recent releases, authoritative sources, independent corroboration, specific capabilities, and clear search intent. Reject generic AI news, consumer-only apps, vague thought leadership, fabricated claims, speculation, and tools without a concrete developer use case.

For the hook field: write it as a genuine tension a developer would want resolved, not a headline summary. Use one of: a contrarian claim ("X breaks the rule everyone follows about Y"), a mistake warning ("most developers get Z wrong"), a numbered promise ("N things changed"), or a concrete before/after gap. Sharpen the framing, never the facts -- the hook must still be fully supported by the claims.

${topicArchive.length ? `PERMANENT EXCLUSION ARCHIVE -- videos already rendered: ${topicArchive.join('; ')}. Never choose any archived tool or substantially equivalent topic, even if it has a new release or slightly different name.` : ''}

Choose exactly 5 distinct candidates from different categories when the evidence allows, ranked best-first. recommended_topic must equal candidates[0]. Every candidate must include the full evidence and SEO fields shown in the schema, including at least one exact source-backed claim, so any unused candidate can safely replace the first choice. Use two independent sources per candidate when available. Every factual claim must cite an exact source_url from the material.

Create an SEO brief around natural developer search language. Titles should promise a concrete, specific benefit -- prefer a number, a contrast, or a named limitation over generic phrasing like "X: what it does", so the title creates a real curiosity gap while staying literally true to the evidence. Limit hashtags to 5-8.

Return ONLY valid JSON matching this schema:
${JSON.stringify(schema)}

RANKED SOURCE MATERIAL:
${JSON.stringify(sourceItems)}`;
return [{json:{prompt,source_count:sourceItems.length,sources:sourceItems,scoring_version:'developer-tools-v2-balanced'}}];

const rawItems = $input.all().map((item) => item.json);
const now = Date.now();
const developerTerms = ['developer', 'coding', 'code', 'agent', 'agentic', 'mcp', 'model context protocol', 'ide', 'cli', 'sdk', 'api', 'automation', 'workflow', 'testing', 'evaluation', 'observability', 'open source', 'framework', 'debug', 'deploy', 'database', 'security', 'performance'];
const harnessTerms = ['agent harness', 'orchestration', 'tool calling', 'computer use', 'memory', 'evals', 'sandbox', 'guardrail', 'tracing', 'prompt management'];
const categoryRules = [
  ['security', ['security', 'vulnerability', 'cve', 'supply chain', 'malware', 'patch']],
  ['databases', ['database', 'postgres', 'mysql', 'sqlite', 'query engine', 'storage']],
  ['testing', ['testing', 'unit test', 'evaluation', 'evals', 'benchmark']],
  ['observability', ['observability', 'tracing', 'telemetry', 'monitoring']],
  ['deployment', ['deploy', 'deployment', 'container', 'serverless', 'cloud']],
  ['languages', ['programming language', 'compiler', 'runtime', 'typescript', 'javascript', 'python', 'rust']],
  ['performance', ['performance', 'latency', 'faster', 'optimization', 'build time']],
  ['agents', ['agent', 'agentic', 'mcp', 'tool calling', 'computer use', 'harness']],
  ['automation', ['automation', 'workflow', 'cli']],
  ['frameworks', ['framework', 'sdk', 'api', 'open source']],
];
const authorityWeights = { 'openai.com': 18, 'github.blog': 18, 'huggingface.co': 17, 'blog.google': 17, 'aws.amazon.com': 16, 'vercel.com': 15, 'blog.jetbrains.com': 15, 'producthunt.com': 10, 'dev.to': 8 };
const normalized = [];
const seen = new Set();
for (const item of rawItems) {
  const sourceUrl = String(item.link ?? item.guid ?? '').trim();
  if (!sourceUrl || seen.has(sourceUrl)) continue;
  seen.add(sourceUrl);
  const publisher = (sourceUrl.split('://')[1] ?? '').split('/')[0].split('?')[0].split('#')[0].replace(/^www\./, '').toLowerCase() || 'unknown';
  const title = String(item.title ?? '').trim();
  const summary = String(item.contentSnippet ?? item.content ?? item.description ?? '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 900);
  const engagementPoints = Number(summary.match(/points:\s*(\d+)/i)?.[1] ?? NaN);
  const engagementComments = Number(summary.match(/comments:\s*(\d+)/i)?.[1] ?? NaN);
  const searchable = `${title} ${summary}`.toLowerCase();
  const publishedAt = item.isoDate ?? item.pubDate ?? item.updated ?? '';
  const publishedMs = Date.parse(publishedAt);
  const ageDays = Number.isFinite(publishedMs) ? Math.max(0, (now - publishedMs) / 86400000) : 365;
  const recencyScore = ageDays <= 2 ? 30 : ageDays <= 7 ? 24 : ageDays <= 14 ? 17 : ageDays <= 30 ? 10 : 3;
  const developerHits = developerTerms.filter((term) => searchable.includes(term));
  const harnessHits = harnessTerms.filter((term) => searchable.includes(term));
  const developerRelevance = Math.min(30, developerHits.length * 5 + Math.min(4, harnessHits.length));
  const authorityScore = Object.entries(authorityWeights).find(([domain]) => publisher.includes(domain))?.[1] ?? 6;
  const toolTokens = [...new Set(title.toLowerCase().match(/[a-z][a-z0-9+.-]{2,}/g) ?? [])].filter((token) => !developerTerms.includes(token) && !['with', 'from', 'your', 'this', 'that', 'the', 'and', 'for', 'new'].includes(token));
  const contentCategory = categoryRules.find(([, terms]) => terms.some((term) => searchable.includes(term)))?.[0] ?? 'general-engineering';
  normalized.push({ title, summary, source_url: sourceUrl, publisher, content_category: contentCategory, published_at: publishedAt, age_days: Math.round(ageDays * 10) / 10, recency_score: recencyScore, developer_relevance: developerRelevance, authority_score: authorityScore, matched_developer_terms: developerHits, matched_harness_terms: harnessHits, tool_tokens: toolTokens.slice(0, 8), engagement_points: Number.isFinite(engagementPoints) ? engagementPoints : null, engagement_comments: Number.isFinite(engagementComments) ? engagementComments : null });
}
const tokenSources = new Map();
for (const item of normalized) for (const token of item.tool_tokens) {
  if (!tokenSources.has(token)) tokenSources.set(token, new Set());
  tokenSources.get(token).add(item.publisher);
}
for (const item of normalized) {
  const crossSourceMentions = Math.max(1, ...item.tool_tokens.map((token) => tokenSources.get(token)?.size ?? 1));
  const momentumScore = Math.min(22, (crossSourceMentions - 1) * 7 + Math.min(8, item.tool_tokens.length));
  const engagementScore = item.engagement_points != null ? Math.min(20, Math.round(Math.log2(item.engagement_points + (item.engagement_comments ?? 0) + 1) * 2.5)) : 0;
  item.cross_source_mentions = crossSourceMentions;
  item.momentum_score = momentumScore;
  item.engagement_score = engagementScore;
  item.trend_score = Math.min(120, item.recency_score + item.developer_relevance + item.authority_score + momentumScore + engagementScore);
  item.seo_terms = [...new Set([...item.matched_developer_terms, ...item.matched_harness_terms, ...item.tool_tokens.slice(0, 4)])].slice(0, 10);
}
const ranked = normalized.filter((item) => item.developer_relevance >= 5).sort((a, b) => b.trend_score - a.trend_score).slice(0, 60);
if (ranked.length < 5) throw new Error('INSUFFICIENT_DEVELOPER_TOOL_SIGNALS');
return ranked.map((json) => ({ json }));

const originalPrompt = $items('Build Research Prompt')[0]?.json?.prompt ?? '';
const statusCode = Number($json.statusCode ?? 200);
const body = $json.body ?? $json;
const text = Array.isArray(body?.content) ? body.content.filter((block) => block?.type === 'text' && typeof block.text === 'string').map((block) => block.text).join('\n').trim() : '';
const errorType = String(body?.error?.type ?? body?.type ?? '').trim();
if (statusCode >= 200 && statusCode < 300 && text) {
  return [{ json: { use_qwen_fallback: false, response: text, research_provider: 'anthropic', research_model: body?.model ?? 'claude', prompt: originalPrompt } }];
}
const fallbackReason = statusCode < 200 || statusCode >= 300 ? `${statusCode}_${errorType || 'http_error'}` : 'empty_response';
return [{ json: { use_qwen_fallback: true, prompt: originalPrompt, research_provider: 'qwen-fallback', fallback_reason: fallbackReason } }];

const promptItem = $items('Build Peter and Stewie Dialogue Prompt')[0]?.json ?? {};
const statusCode = Number($json.statusCode ?? 200);
const body = $json.body ?? $json;
const text = Array.isArray(body?.content) ? body.content.filter((block) => block?.type === 'text' && typeof block.text === 'string').map((block) => block.text).join('\n').trim() : '';
const errorType = String(body?.error?.type ?? body?.type ?? '').trim();
let dialogueValid = false;
if (statusCode >= 200 && statusCode < 300 && text) {
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = String(fenced?.[1] ?? text).trim();
  try {
    const parsed = JSON.parse(candidate);
    const expected = ['peter', 'stewie', 'peter', 'stewie', 'peter', 'stewie'];
    const turns = Array.isArray(parsed.turns) ? parsed.turns : [];
    const wordCount = turns.reduce((sum, turn) => sum + String(turn.text ?? '').trim().split(/\s+/).filter(Boolean).length, 0);
    dialogueValid = turns.length === 6 && turns.every((turn, index) => String(turn.speaker ?? '').toLowerCase().trim() === expected[index] && String(turn.text ?? '').trim()) && wordCount >= 48;
  } catch {}
}
if (dialogueValid) {
  return [{ json: { use_qwen_fallback: false, response: text, dialogue_provider: 'anthropic', dialogue_model: body?.model ?? 'claude', prompt: promptItem.prompt, research: promptItem.research, seo_brief: promptItem.seo_brief } }];
}
const fallbackReason = statusCode < 200 || statusCode >= 300 ? `${statusCode}_${errorType || 'http_error'}` : text ? 'invalid_dialogue' : 'empty_response';
return [{ json: { use_qwen_fallback: true, prompt: promptItem.prompt, research: promptItem.research, seo_brief: promptItem.seo_brief, dialogue_provider: 'qwen-fallback', fallback_reason: fallbackReason } }];

const payload = $json;
let raw = '';
if (typeof payload === 'string') raw = payload;
else if (typeof payload.body === 'string') raw = payload.body;
else if (typeof payload.data === 'string') raw = payload.data;
else if (typeof payload.response === 'string') raw = payload.response;
else raw = JSON.stringify(payload);
if (!raw) throw new Error('RESEARCH_EMPTY_RESPONSE');
let generated = raw;
try { generated = JSON.parse(raw).response ?? raw; } catch {
  const lines = raw.split(/\r?\n/).filter(Boolean);
  const chunks = [];
  let isNdjson = lines.length > 1;
  for (const line of lines) {
    try { chunks.push(JSON.parse(line)); } catch { isNdjson = false; break; }
  }
  if (isNdjson && chunks.every((chunk) => typeof chunk.response === 'string')) generated = chunks.map((chunk) => chunk.response).join('');
}
const fenced = generated.match(/```(?:json)?\s*([\s\S]*?)```/i);
const candidate = String(fenced?.[1] ?? generated).trim();
let research;
const end = candidate.lastIndexOf('}');
for (const start of [0, ...[...candidate.matchAll(/\{/g)].map((match) => match.index)]) {
  if (end < start) continue;
  try {
    const parsed = JSON.parse(candidate.slice(start, end + 1));
    if (parsed?.recommended_topic?.claims?.length) { research = parsed; break; }
  } catch {}
}
if (!research) throw new Error('RESEARCH_INVALID_JSON: no valid JSON object with recommended_topic.claims found');
const provider = payload.research_provider ?? 'qwen-fallback';
const model = payload.research_model ?? 'tushin-agent:latest';
return [{ json: { research, researched_at: new Date().toISOString(), research_provider: provider, model, requires_human_review: true } }];

const research = $json.research;
const topic = research?.recommended_topic;
if (!topic) throw new Error('SEO_MISSING_RECOMMENDED_TOPIC');
const incoming = topic.seo_brief ?? {};
const toolName = String(topic.tool_name ?? topic.topic ?? 'AI developer tool').trim();
const primaryKeyword = String(incoming.primary_keyword ?? `${toolName} for developers`).trim();
const relatedKeywords = [...new Set((Array.isArray(incoming.related_keywords) ? incoming.related_keywords : []).map((value) => String(value).trim()).filter(Boolean))].slice(0, 8);
const titleOptions = [...new Set((Array.isArray(incoming.title_options) ? incoming.title_options : []).map((value) => String(value).trim()).filter(Boolean))].slice(0, 5);
if (!titleOptions.length) titleOptions.push(`${toolName}: the developer workflow it improves`);
const hashtags = [...new Set((Array.isArray(incoming.hashtags) ? incoming.hashtags : []).map((value) => `#${String(value).replace(/^#/, '').replace(/[^A-Za-z0-9_]/g, '')}`).filter((value) => value.length > 1))].slice(0, 8);
for (const fallback of ['#AITools', '#DeveloperTools', '#Coding']) { if (hashtags.length >= 5) break; if (!hashtags.includes(fallback)) hashtags.push(fallback); }
const seoBrief = { primary_keyword: primaryKeyword, related_keywords: relatedKeywords, search_intent: incoming.search_intent ?? 'informational', title_options: titleOptions, description: String(incoming.description ?? topic.one_line_value ?? topic.why_it_matters ?? '').trim(), hashtags };
research.recommended_topic.seo_brief = seoBrief;
return [{ json: { ...$json, research, seo_brief: seoBrief } }];

const research = $items('Finalize SEO Brief')[0]?.json?.research;
if (!research?.recommended_topic) throw new Error('SCRIPT_MISSING_RESEARCH');
const topic = research.recommended_topic;
const prompt = `Write a clean, evidence-based dialogue for a 30–60 second vertical video about the recommended AI developer tool below. Return exactly six short alternating turns, beginning with Peter.

Dialogue structure -- this is an ARGUMENT, not a briefing. Peter and Stewie hold opposing positions on the tool and push back on each other's specific words; neither one just explains something to a passive listener.
1. Peter opens with the hook: the single boldest, most surprising claim about the tool, stated in one short sentence of 18 words or fewer -- a stance, not a description. This line is the only thing standing between the viewer and a scroll past, so it must land in the first 5-10 seconds and cannot be buried behind a wind-up, a greeting, or context-setting.
2. Stewie directly disagrees, naming a real limitation, cost, or reason to doubt the claim.
3. Peter defends the claim with one concrete, evidence-backed detail that answers Stewie's specific objection.
4. Stewie escalates with a sharper counter-argument or a harder edge case -- not a generic "how is it useful" question.
5. Peter counters again with a second specific, evidence-backed point that directly rebuts turn 4.
6. Stewie delivers a genuine verdict: concede the point while landing a final jab, or hold the disagreement -- never a neat, tidy agreement. The tension should feel unresolved enough that the viewer picks a side.

Focus on one primary tool and one coherent use case. Do not combine unrelated products, models, or claims in the same dialogue. Every turn must be one sentence: complete, conversational, and written with simple grammar and a clear subject. Turn 0's 18-word hook limit is a hard requirement, not a suggestion -- before returning, count its words and shorten it if it runs long, since a slow opening line is a failed video even if every other turn is perfect. Keep the dialogue natural and conversational with no filler or padding. Peter is plain-spoken, confident, and mildly funny; Stewie is precise, skeptical, and cutting. They are arguing with each other, not narrating to the camera. Keep every line clean, natural, and easy to say aloud. Name the tool early, use the primary SEO keyword naturally at most once, and never include stage directions, headings, URLs, profanity, keyword stuffing, sentence fragments, or unsupported hype. Use only facts from the research package.

After writing the dialogue, plan 8–12 distinct visual cues. Every one of the six turns (turn_index 0 through 5) MUST appear in the visuals array at least once — this is a hard requirement, not a suggestion. Before returning, re-read your own six turns and check that turn_index 0, 1, 2, 3, 4, and 5 each appear at least once in visuals; if any turn is missing, add a cue for it before adding a second cue to a denser turn. A turn with zero cues fails the whole video, so never skip one because it feels abstract — find the most literal, concrete thing that turn's line could point to (a specific UI element, a specific number, a reaction shot) rather than leaving it uncovered. Each cue must name an exact phrase spoken in its zero-based turn_index, a focused image-search query, kind logo or screenshot, a visual_purpose of identity, interface, mechanism, outcome, evidence, reaction, or context, and a source_url to the exact product, documentation, repository, or evidence page. Prefer official UI screenshots, GitHub README diagrams, code, terminal output, benchmarks, and readable product imagery. Stock images are allowed only for reaction or context and must never serve as evidence for a named product. Never request generic approval/review imagery, generic article headers, government documents, unrelated products, or repeated variants of the same artwork. Claude Vision will reject irrelevant candidates and the run will fail unless eight distinct images survive, so choose visually provable beats and precise queries.

Return ONLY JSON: {"title":"","focus":"","turns":[{"speaker":"peter","text":""},{"speaker":"stewie","text":""},{"speaker":"peter","text":""},{"speaker":"stewie","text":""},{"speaker":"peter","text":""},{"speaker":"stewie","text":""}],"visuals":[{"turn_index":0,"phrase":"exact spoken phrase","query":"tool name screenshot","kind":"screenshot","visual_purpose":"interface","source_url":"https://official-source-page"}]}
RECOMMENDED RESEARCH:
${JSON.stringify(topic)}`;
return [{ json: { prompt, research, seo_brief: $items('Finalize SEO Brief')[0]?.json?.seo_brief } }];

const payload = $json;
let raw = '';
if (typeof payload === 'string') raw = payload;
else if (typeof payload.data === 'string') raw = payload.data;
else if (typeof payload.body === 'string') raw = payload.body;
else if (typeof payload.response === 'string') raw = payload.response;
else raw = JSON.stringify(payload);
if (!raw) throw new Error('DIALOGUE_EMPTY_RESPONSE');
let generated = raw;
try { generated = JSON.parse(raw).response ?? raw; } catch {
  const lines = raw.split(/\r?\n/).filter(Boolean);
  const chunks = [];
  let isNdjson = lines.length > 1;
  for (const line of lines) {
    try { chunks.push(JSON.parse(line)); } catch { isNdjson = false; break; }
  }
  if (isNdjson && chunks.every((chunk) => typeof chunk.response === 'string')) generated = chunks.map((chunk) => chunk.response).join('');
}
const fenced = generated.match(/```(?:json)?\s*([\s\S]*?)```/i);
const candidate = String(fenced?.[1] ?? generated).trim();
let dialoguePackage;
const end = candidate.lastIndexOf('}');
for (const start of [0, ...[...candidate.matchAll(/\{/g)].map((match) => match.index)]) {
  if (end < start) continue;
  try {
    const parsed = JSON.parse(candidate.slice(start, end + 1));
    if (Array.isArray(parsed.turns)) { dialoguePackage = parsed; break; }
  } catch {}
}
if (!dialoguePackage || dialoguePackage.turns.length !== 6) throw new Error('DIALOGUE_REQUIRES_SIX_TURNS');
const expected = ['peter', 'stewie', 'peter', 'stewie', 'peter', 'stewie'];
const dialogue = dialoguePackage.turns.map((turn, index) => {
  const speaker = String(turn.speaker ?? '').toLowerCase().trim();
  if (speaker !== expected[index]) throw new Error(`DIALOGUE_SPEAKER_ORDER:${index}`);
  const text = String(turn.text ?? '').replace(/\s+/g, ' ').trim();
  if (!text) throw new Error(`DIALOGUE_EMPTY_TURN:${index}`);
  return { speaker, text, turn_index: index, audio_path: `/media/databases-performance-trend-dialogue-${index}-${speaker}.wav` };
});
const wordCount = dialogue.reduce((sum, turn) => sum + turn.text.split(/\s+/).length, 0);
if (wordCount < 48) throw new Error(`DIALOGUE_WORD_COUNT:${wordCount}`);
const metadata = { title: String(dialoguePackage.title ?? ''), focus: String(dialoguePackage.focus ?? ''), visuals: Array.isArray(dialoguePackage.visuals) ? dialoguePackage.visuals : [], research: payload.research };
return dialogue.map((turn) => ({ json: { ...turn, dialogue, ...metadata } }));

const jobs = $items('Normalize Peter and Stewie Dialogue').map((item) => item.json).sort((a, b) => a.turn_index - b.turn_index);
if (jobs.length !== 6) throw new Error(`RENDER_REQUIRES_SIX_DIALOGUE_TURNS:${jobs.length}`);
const first = jobs[0];
const visualCues = first.visuals || [];
// Fail here -- before any image search, download, or judging happens -- rather than only at the
// very end of visual discovery. The script prompt asks Claude for a cue on every turn, but that
// instruction isn't always followed; catching a coverage gap this early turns a confusing late
// VISUAL_PREFLIGHT_FAILED:N_TURNS_COVERED into an accurate, cheap, immediate error instead.
const coveredTurns = new Set(visualCues.map((cue) => Number(cue.turn_index)).filter(Number.isInteger));
if (coveredTurns.size < 6) throw new Error(`DIALOGUE_CUES_MISSING_TURNS:${coveredTurns.size}_OF_6`);
const dialogue = jobs.map((job) => ({ speaker: job.speaker, text: job.text, turn_index: job.turn_index, audioPath: job.audio_path }));
const research = $items('Build Peter and Stewie Dialogue Prompt')[0].json.research;
return [{json:{sourceVideo:'/media/source.mp4',voiceOverlay:null,pngOverlay:null,characterImages:{peter:'/media/peter.png',stewie:'/media/stewie.png'},durationInFrames:1800,dialogue,visualCues,visuals:[],title:first.title,focus:first.focus,research,requires_human_review:true}}];

const context = $items('Build Dialogue Audio and Subtitle Render Job')[0]?.json ?? {};
const topic = context.research?.recommended_topic ?? {};
const seoBrief = topic.seo_brief ?? {};
const dialogueLines = (context.dialogue || []).map((turn) => `${turn.speaker}: ${turn.text}`).join('
');
const prompt = `Write an Instagram Reel caption for a short animated dialogue video between Peter and Stewie about ${String(topic.tool_name ?? topic.topic ?? 'an AI developer tool')}.

Hook: ${topic.hook ?? ''}
One-line value: ${topic.one_line_value ?? ''}

Dialogue:
${dialogueLines}

Existing SEO keywords: ${(seoBrief.related_keywords || []).join(', ')}
Existing hashtag ideas: ${(seoBrief.hashtags || []).join(' ')}

Write a short, punchy caption (1-3 sentences, no hashtags inline) that hooks a developer scrolling Instagram, then 5-8 relevant hashtags. Reuse or refine the existing hashtag ideas above rather than inventing unrelated ones. No emojis unless they add real value. No stage directions.

Return ONLY JSON: {"caption":"","hashtags":["#Tag1","#Tag2"]}`;
return [{ json: { prompt, outputLocation: $json.render?.outputLocation ?? $json.outputLocation, seo_brief: seoBrief } }];

const promptItem = $items('Build Instagram Caption Prompt')[0]?.json ?? {};
const statusCode = Number($json.statusCode ?? 200);
const body = $json.body ?? $json;
const text = Array.isArray(body?.content) ? body.content.filter((block) => block?.type === 'text' && typeof block.text === 'string').map((block) => block.text).join('\n').trim() : '';
let caption; let captionSource = 'seo_fallback';
if (statusCode >= 200 && statusCode < 300 && text) {
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = String(fenced?.[1] ?? text).trim();
  try {
    const parsed = JSON.parse(candidate);
    const parsedCaption = String(parsed.caption ?? '').trim();
    const hashtags = Array.isArray(parsed.hashtags) ? parsed.hashtags.map((tag) => String(tag).trim()).filter(Boolean) : [];
    if (parsedCaption && hashtags.length) { caption = `${parsedCaption}\n\n${hashtags.join(' ')}`; captionSource = 'claude'; }
  } catch {}
}
if (!caption) {
  const seoBrief = promptItem.seo_brief ?? {};
  const description = String(seoBrief.description ?? '').trim();
  const hashtags = Array.isArray(seoBrief.hashtags) ? seoBrief.hashtags : [];
  caption = [description, hashtags.join(' ')].filter(Boolean).join('\n\n');
}
if (!caption) throw new Error('INSTAGRAM_CAPTION_UNAVAILABLE');
return [{ json: { caption, captionSource, outputLocation: promptItem.outputLocation } }];

const context = $items('Build Dialogue Audio and Subtitle Render Job')[0]?.json ?? {};
const topic = context.research?.recommended_topic ?? {};
const rawTitle = `${topic.tool_name ?? topic.topic ?? 'AI Tool'}: ${topic.hook ?? ''}`.trim();
const title = rawTitle.length > 100 ? `${rawTitle.slice(0, 99).trimEnd()}…` : rawTitle;
const caption = String($json.caption ?? '').trim();
const description = /#shorts/i.test(caption) ? caption : `${caption}\n\n#Shorts`.trim();
return [{ json: { title, description, outputLocation: $json.outputLocation } }];
